INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 33, 'theory', 'Quiz: collections');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 33, 0, 'c = Counter("aab"). What is c["z"]?', '["KeyError", "0", "None", "1"]', 1, 'For a counter, a missing key gives zero, not an error.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 33, 1, 'd = defaultdict(list); d[''x'']: what happened to the dictionary?', '["Nothing: there is no key, an error was returned", "An entry ''x'': [] appeared", "Python returned None", "The dictionary was cleared"]', 1, 'Even reading a missing key creates an entry with the default value.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 33, 2, 'Why is deque better than a list for a queue?', '["deque is shorter to write", "deque has fast operations at both ends, while removing from the front of a list shifts all elements", "deque stores less data", "A list cannot be used as a queue"]', 1, 'popleft on a deque takes constant time, while list.pop(0) shifts the remaining elements.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 33, 3, 'What does a heapq heap guarantee?', '["The list is fully sorted", "The smallest element is always at the start (index 0)", "Elements go in descending order", "All elements are unique"]', 1, 'A heap is only partially ordered: only the minimum at the start is guaranteed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 33, 4, 'What will bisect.bisect_left([10, 20, 20, 30], 20) return?', '["0", "1", "2", "3"]', 1, 'The position before the first occurrence of 20 is index 1 (bisect_right would return 3).');
